import {createHash,randomUUID} from 'node:crypto';
import {planAnswerCollection} from './answer-manifest.mjs';
import {submissionBundle,MAX_BUNDLE_BYTES} from './submission-bundle.mjs';
const validUser=(u,clock)=>u&&Number.isSafeInteger(u.studentId)&&u.studentId>0&&Number.isSafeInteger(u.attemptId)&&u.attemptId>0&&Number.isFinite(u.deadline)&&typeof u.device==='string'&&u.device&&clock()<u.deadline;
export async function createCandidateBundle(service,input,token){
 const {quiz,task,ids}=input||{};if(!Number.isSafeInteger(quiz)||quiz<1||typeof token!=='string'||!token||typeof task!=='string'||!task||!Array.isArray(ids)||ids.length<2||ids.length>19||new Set(ids).size!==ids.length||ids.some(id=>typeof id!=='string'||!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(id))||typeof service.read!=='function')throw Error('打包请求无效');
 if(!Number.isSafeInteger(service.maxBundleBytes)||service.maxBundleBytes<1||service.maxBundleBytes>MAX_BUNDLE_BYTES)throw Error('合并大小上限无效');if(service.active>=service.maxConcurrent)throw Error('上传繁忙');service.active++;let lock,owned=false;
 try{const first=await service.authorize(quiz,token);if(!validUser(first,service.clock))throw Error('考试不可提交');lock=quiz+':'+first.studentId;if(service.locks.has(lock))throw Error('该考生已有上传进行中');service.locks.add(lock);owned=true;
  const exam='exam-'+quiz,student=String(first.studentId),existing=await service.list(exam,student);if(!Array.isArray(existing)||existing.length>=service.maxVersions)throw Error('答案版本已满');const selected=ids.map(id=>existing.find(r=>r.id===id));if(selected.some(r=>!r||r.exam!==exam||r.student!==student||r.taskId!==task||r.device!=='candidate-web'||!Number.isSafeInteger(r.size)||r.size<1)||selected.reduce((n,r)=>n+r.size,0)>service.maxBundleBytes)throw Error('所选文件不可用');
  const files=[];for(const record of selected){const ext=record.path.split('.').at(-1).toLowerCase();if(await service.validateTask(quiz,task,ext)!==task)throw Error('任务不可用');const file=await service.read(record.id);if(!file?.record||file.record.id!==record.id||file.record.sha256!==record.sha256||file.record.path!==record.path||file.record.size!==record.size||file.record.device!==record.device||file.record.exam!==exam||file.record.student!==student||file.record.taskId!==task)throw Error('答案已变化');files.push(file)}
  const data=submissionBundle(files);if(data.length>service.maxBundleBytes||existing.reduce((n,x)=>n+(Number.isSafeInteger(x.size)?x.size:service.maxTotalBytes),0)+data.length>service.maxTotalBytes)throw Error('答案容量已满');const second=await service.authorize(quiz,token);if(!validUser(second,service.clock)||second.studentId!==first.studentId||second.attemptId!==first.attemptId||second.deadline!==first.deadline||second.device!==first.device)throw Error('考试状态已变化');for(const r of selected)if(await service.validateTask(quiz,task,r.path.split('.').at(-1).toLowerCase())!==task)throw Error('任务状态已变化');if(service.clock()>=first.deadline)throw Error('考试已结束');
  const name='合并答卷-'+randomUUID()+'.zip',sha256=createHash('sha256').update(data).digest('hex'),plan=planAnswerCollection({exam,student,device:'candidate-web',available:['candidate-web'],files:[{path:name,size:data.length,sha256}]})[0];plan.taskId=task;service.markStarted(exam);const result=await service.save(plan,data);if(!result||result.exam!==exam||result.student!==student||result.taskId!==task||result.sha256!==sha256||typeof result.id!=='string')throw Error('答案保存未确认');return {id:result.id,exam,student,name,size:data.length,sha256,taskId:task};
 }finally{if(owned)service.locks.delete(lock);service.active--}
}
